select.if:
SELECT * FROM (
UNION ALL
) ORDER BY tradeDateText DESC

mapper.sql:
SELECT 'root' parentId, concat_ws('',T1.TOTLE_TRADE_ID,'_',#{status_02}) childId , T1.TOTLE_TRADE_ID totleTradeId , CASE WHEN T1.TRADE_STATUS = #{TRADE_STATUS_01} THEN #{status_02} WHEN T1.TRADE_STATUS = #{TRADE_STATUS_03} THEN #{status_03} ELSE '' END validStatus , DATE_FORMAT(T1.TRADE_DATE,'%Y-%m-%d') tradeDateText , T2.COUNTER_NAME counterId , T1.COUNTER_TRADER counterTrader , T1.PS ps , T1.TRADE_AMT tradeAmt , IFNULL(T1.RATE, 0) * 100 rate , T1.REPO_TERM repoTerm , T1.SETTLE_SPEED settleSpeedText , T1.DELIVERY_TYPE deliveryType , T1.M_DELIVERY_TYPE mDeliveryType , T1.CLEAR_TYPE clearType , DATE_FORMAT(T1.EFF_TIME,'%Y-%m-%d HH24:mi:ss') effTime , T1.REMARK remark , T3.SEC_ACCT_ID secAcctId , T3.REGIST_ORG registOrg , T3.SEC_ACCT_NAME secAcctName , T4.BUSI_ACCT_NO acctNo , T4.ACCT_NAME acctName , T4.BANK_DEP acctBankDep , T4.LARGE_PAYNO acctBankDepoPayno , 'CNY' bondCcy , 'CNY' settleCcy , '' workflowId, '' workflowStatus FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN MST_COUNTER_PARTY T2 ON T1.COUNTER_ID = T2.COUNTER_ID LEFT JOIN STL_SEC_ACCT_INFO T3 ON T1.SEC_MANAGE_ACCT_ID = T3.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO T4 ON T3.TRD_ACCT_ID = T4.ACCT_NO AND T3.TRD_ACCT_CCY = T4.CCY WHERE T1.BUSI_TYPE = #{COMMON_BUSINESS_TYPE_TRD70} AND T1.IS_CANCEL = #{IS_CANCEL_N}
AND T1.TRADE_STATUS = #{TRADE_STATUS_01}
AND T1.TRADE_STATUS = #{TRADE_STATUS_03}
AND (T1.TRADE_STATUS = #{TRADE_STATUS_01} OR T1.TRADE_STATUS = #{TRADE_STATUS_03})
AND EXISTS ( SELECT 1 FROM TRD_PRODUCT_DEAL_PRE TPD, TRD_PRODUCT_DEAL_ADD_PRE TPDA WHERE TPD.TRADE_ID = TPDA.TRADE_ID AND TPD.TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID AND TPDA.PORTFOLIO_ID IN ( SELECT PPA.PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY PPA WHERE PPA.USER_ID = #{loginUserName} ) )
